fn iabs(v: i32) -> i32 {
    if v < 0 { -v } else { v }
}

fn frame(t: i32) {
    let tab = [0, 25, 49, 71, 90, 106, 117, 124, 127, 124, 117, 106, 90, 71, 49, 25, 0, -25, -49, -71, -90, -106, -117, -124, -127, -124, -117, -106, -90, -71, -49, -25];
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cx: i32 = w / 2;
    let cy: i32 = h / 2;
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(2, (cx + 150) * 16);
        host::display::state_set(3, cy * 16);
        host::display::state_set(4, 0);
        host::display::state_set(5, 218);
        host::display::state_set(6, 0);
    }
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(7);
    host::display::state_set(7, down);
    let tap: bool = down == 1 && prev == 0;
    let mut x: i32 = host::display::state_get(2);
    let mut y: i32 = host::display::state_get(3);
    let mut vx: i32 = host::display::state_get(4);
    let mut vy: i32 = host::display::state_get(5);
    let status: i32 = host::display::state_get(6);
    if status == 0 {
        if tap {
            vx = vx + vx / 6;
            vy = vy + vy / 6;
        }
        vx = vx + (cx * 16 - x) / 128;
        vy = vy + (cy * 16 - y) / 128;
        vx = vx - vx / 512;
        vy = vy - vy / 512;
        x = x + vx;
        y = y + vy;
        host::display::state_set(2, x);
        host::display::state_set(3, y);
        host::display::state_set(4, vx);
        host::display::state_set(5, vy);
        let mut a: i32 = iabs(x / 16 - cx);
        let mut b: i32 = iabs(y / 16 - cy);
        if a < b {
            let tmp: i32 = a;
            a = b;
            b = tmp;
        }
        let d: i32 = a + b / 2;
        if d < 40 { host::display::state_set(6, 1); }
        if d > 235 { host::display::state_set(6, 2); }
        host::display::clear(0x04040a);
        let mut i: i32 = 0;
        while i < 16 {
            let ang: i32 = i * 2;
            host::display::fill_rect(cx + tab[ang] * 235 / 127 - 1, cy + tab[(ang + 8) & 31] * 235 / 127 - 1, 2, 2, 0x282838);
            i = i + 1;
        }
        host::display::fill_rect(cx - 32, cy - 32, 64, 64, 0x3060a0);
        host::display::fill_rect(x / 16 - 4, y / 16 - 4, 8, 8, 0xe0e0e0);
        host::display::draw_string(8, 8, "ALT", 0x707070, 1);
        let mut alt: i32 = d - 40;
        if alt < 0 { alt = 0; }
        host::display::draw_number(50, 8, alt, 0xffffff, 1);
        host::display::draw_string(8, 24, "TAP = BOOST", 0x505050, 1);
    } else {
        host::display::clear(0x04040a);
        if status == 1 {
            host::display::draw_string(cx - 90, cy - 20, "DEORBITED", 0xff5040, 3);
        } else {
            host::display::draw_string(cx - 80, cy - 20, "ESCAPED", 0x60c0ff, 3);
        }
        host::display::draw_string(cx - 70, cy + 30, "TAP TO RELAUNCH", 0x808080, 1);
        if tap { host::display::state_set(0, 0); }
    }
    host::display::present();
}
